local M = {}

-- 1. Base Object-Oriented Framework (ZO_Object & Subclassing)
ZO_Object = ZO_Object or {}
function ZO_Object:Subclass()
    local newClass = {}
    for k, v in pairs(self) do
        newClass[k] = v
    end
    newClass.__index = newClass
    setmetatable(newClass, {
        __index = self,
        __call = function(cls, ...)
            return cls:New(...)
        end,
    })
    return newClass
end

function ZO_Object:New(...)
    local instance = setmetatable({}, self)
    if instance.Initialize then
        instance:Initialize(...)
    end
    return instance
end

-- 2. Callback Event System (ZO_CallbackObject)
ZO_CallbackObject = ZO_CallbackObject or ZO_Object:Subclass()
function ZO_CallbackObject:Initialize()
    self._callbacks = {}
end

function ZO_CallbackObject:RegisterCallback(eventName, callback)
    self._callbacks = self._callbacks or {}
    self._callbacks[eventName] = self._callbacks[eventName] or {}
    table.insert(self._callbacks[eventName], callback)
end

function ZO_CallbackObject:UnregisterCallback(eventName, callback)
    if not self._callbacks or not self._callbacks[eventName] then return end
    for i, cb in ipairs(self._callbacks[eventName]) do
        if cb == callback then
            table.remove(self._callbacks[eventName], i)
            break
        end
    end
end

function ZO_CallbackObject:FireCallbacks(eventName, ...)
    if not self._callbacks or not self._callbacks[eventName] then return end
    for _, cb in ipairs(self._callbacks[eventName]) do
        cb(...)
    end
end

