-- 4. Native Control Hierarchy (GuiRoot, CreateControl)
local function CreateControlMock(name, parent, controlType)
    local ctrl = {
        _name = name,
        _parent = parent,
        _type = controlType or CT_CONTROL,
        _hidden = false,
        _width = 100,
        _height = 100,
        _alpha = 1.0,
        _text = "",
        _font = "",
        _texture = "",
        _anchors = {},
        _handlers = {},
        _children = {},
        _mouseEnabled = true,
    }

    function ctrl:GetName() return self._name end
    function ctrl:GetType() return self._type end
    function ctrl:SetHidden(hidden) self._hidden = not not hidden end
    function ctrl:IsHidden() return self._hidden end
    function ctrl:SetDimensions(w, h) self._width = w; self._height = h end
    function ctrl:GetDimensions() return self._width, self._height end
    function ctrl:GetWidth() return self._width end
    function ctrl:GetHeight() return self._height end
    function ctrl:SetWidth(w) self._width = w end
    function ctrl:SetHeight(h) self._height = h end
    function ctrl:SetAlpha(alpha) self._alpha = alpha end
    function ctrl:GetAlpha() return self._alpha end
    function ctrl:SetColor(r, g, b, a) self._color = {r=r, g=g, b=b, a=a} end
    function ctrl:GetColor()
        return self._color and self._color.r or 1,
               self._color and self._color.g or 1,
               self._color and self._color.b or 1,
               self._color and self._color.a or 1
    end
    function ctrl:SetText(t) self._text = tostring(t or "") end
    function ctrl:GetText() return self._text end
    function ctrl:SetFont(f) self._font = f end
    function ctrl:GetFont() return self._font end
    function ctrl:SetTexture(tex) self._texture = tex end
    function ctrl:GetTextureFileName() return self._texture end
    function ctrl:SetAnchor(point, relTo, relPoint, x, y)
        table.insert(self._anchors, { point = point, relTo = relTo, relPoint = relPoint, x = x or 0, y = y or 0 })
    end
    function ctrl:ClearAnchors() self._anchors = {} end
    function ctrl:GetNumAnchors() return #self._anchors end
    function ctrl:GetAnchor(i)
        local a = self._anchors[i or 1]
        if a then return true, a.point, a.relTo, a.relPoint, a.x, a.y end
        return false
    end
    function ctrl:SetHandler(eventName, handler) self._handlers[eventName] = handler end
    function ctrl:GetHandler(eventName) return self._handlers[eventName] end
    function ctrl:FireHandler(eventName, ...)
        if self._handlers[eventName] then
            return self._handlers[eventName](self, ...)
        end
    end
    function ctrl:SetMouseEnabled(enabled) self._mouseEnabled = not not enabled end
    function ctrl:IsMouseEnabled() return self._mouseEnabled end
    function ctrl:GetParent() return self._parent end
    function ctrl:SetParent(p) self._parent = p end
    function ctrl:AddChild(c) table.insert(self._children, c) end
    function ctrl:GetNumChildren() return #self._children end
    function ctrl:GetChild(i) return self._children[i] end

    if name and name ~= "" then
        _G[name] = ctrl
    end
    if parent and parent.AddChild then
        parent:AddChild(ctrl)
    end
    return ctrl
end

GuiRoot = GuiRoot or CreateControlMock("GuiRoot", nil, CT_TOPLEVELCONTROL)

function CreateControl(name, parent, controlType)
    return CreateControlMock(name, parent or GuiRoot, controlType)
end

function CreateControlFromVirtual(name, parent, templateName, optionalId)
    local ctrl = CreateControlMock(name, parent or GuiRoot, CT_CONTROL)
    ctrl._template = templateName
    return ctrl
end

-- 5. Scenes and Fragments (ZO_Scene, ZO_SceneGroup, ZO_FadeSceneFragment)
ZO_SceneFragment = ZO_SceneFragment or ZO_CallbackObject:Subclass()
function ZO_SceneFragment:Initialize()
    ZO_CallbackObject.Initialize(self)
    self._state = SCENE_FRAGMENT_HIDDEN
    self._hiddenReasons = {}
    self._sceneShowing = false
end
function ZO_SceneFragment:IsHidden()
    return next(self._hiddenReasons) ~= nil
end
function ZO_SceneFragment:SetHiddenForReason(reason, hidden)
    if hidden then
        self._hiddenReasons[reason] = true
    else
        self._hiddenReasons[reason] = nil
    end
    self:Refresh()
end
function ZO_SceneFragment:Show()
    self._sceneShowing = true
    if self:IsHidden() then
        self:Hide()
        return
    end
    self._state = SCENE_FRAGMENT_SHOWN
    self:FireCallbacks("StateChange", SCENE_FRAGMENT_HIDDEN, SCENE_FRAGMENT_SHOWN)
end
function ZO_SceneFragment:Hide()
    self._state = SCENE_FRAGMENT_HIDDEN
    self:FireCallbacks("StateChange", SCENE_FRAGMENT_SHOWN, SCENE_FRAGMENT_HIDDEN)
end
function ZO_SceneFragment:GetState() return self._state end
function ZO_SceneFragment:Refresh()
    if self._sceneShowing and not self:IsHidden() then
        self:Show()
    else
        self:Hide()
    end
end

ZO_FadeSceneFragment = ZO_FadeSceneFragment or ZO_SceneFragment:Subclass()
function ZO_FadeSceneFragment:Initialize(control)
    ZO_SceneFragment.Initialize(self)
    self.control = control
end
function ZO_FadeSceneFragment:Show()
    self._sceneShowing = true
    if self:IsHidden() then
        self:Hide()
        return
    end
    if self.control and self.control.SetHidden then
        self.control:SetHidden(false)
    end
    ZO_SceneFragment.Show(self)
end
function ZO_FadeSceneFragment:Hide()
    if self.control and self.control.SetHidden then
        self.control:SetHidden(true)
    end
    ZO_SceneFragment.Hide(self)
end

ZO_SimpleSceneFragment = ZO_SimpleSceneFragment or ZO_FadeSceneFragment

ZO_Scene = ZO_Scene or ZO_CallbackObject:Subclass()
function ZO_Scene:Initialize(name, sceneManager)
    ZO_CallbackObject.Initialize(self)
    self.name = name
    self.sceneManager = sceneManager
    self.state = SCENE_HIDDEN
    self.fragments = {}
end
function ZO_Scene:AddFragment(fragment)
    table.insert(self.fragments, fragment)
end
function ZO_Scene:RemoveFragment(fragment)
    for i, f in ipairs(self.fragments) do
        if f == fragment then
            table.remove(self.fragments, i)
            break
        end
    end
end
function ZO_Scene:HasFragment(fragment)
    for _, f in ipairs(self.fragments) do
        if f == fragment then return true end
    end
    return false
end
function ZO_Scene:AddFragmentGroup(group)
    for _, f in ipairs(group) do
        self:AddFragment(f)
    end
end
function ZO_Scene:RemoveFragmentGroup(group)
    for _, f in ipairs(group) do
        self:RemoveFragment(f)
    end
end
function ZO_Scene:GetName() return self.name end
function ZO_Scene:GetState() return self.state end
function ZO_Scene:IsShowing() return self.state == SCENE_SHOWING or self.state == SCENE_SHOWN end
function ZO_Scene:WasShown() return self.state == SCENE_SHOWN end

